"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    return row.get(column, "")


def _number(value: Any) -> Decimal:
    """Legacy numeric context: empty or missing values coerce to zero."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    """Return the first live matching row value, or the legacy empty value."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")

    return ""


def _error(code: str, message: str) -> dict:
    return {"code": code, "message": message, "severity": "BLOCK"}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order header or order line using legacy VRL rule order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            disc_pct = _number(_value(record, "DISC_PCT"))
            if not (disc_pct >= 0 and disc_pct <= 100):
                errors.append(_error("E5001", "Discount out of range"))

        if event == "UPDATE":
            disc_pct = _number(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            role_one = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            role_two = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if disc_pct > 20 and role_one != "MGR" and role_two != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

            old_stat = "" if event == "INSERT" else _value(old, "STAT_CD")
            stat = _value(record, "STAT_CD")
            if old_stat == "I" and stat != "I" and stat != "X":
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > 0):
                errors.append(_error("E5004", "Quantity must be positive"))

        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active_flg = _lookup(
                tables, "PROD_MASTER", "PROD_ID", product_id, "ACTIVE_FLG"
            )
            if active_flg != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
